        return (value: ContactValue) => ({
            header,
            value,
            checked: true,
            field: 'geo',
            type: 'work',
        });
    }
    if (property === 'gender') {
        return (value: ContactValue) => ({
            header,
            value,
            checked: true,
            field: 'gender',
        });
    }
    if (property === 'timezone') {
        return (value: ContactValue) => ({
            header,
            value,
            checked: true,
            field: 'tz',
        });
    }
    if (property === 'organization') {
        return (value: ContactValue) => ({
